import { FlatList, Text } from 'react-native';

type Row = { id: string; title: string };
const ROW_HEIGHT = 72;

export function OrderList({ rows }: { rows: Row[] }) {
  return (
    <FlatList
      data={rows}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => <Text style={{ height: ROW_HEIGHT }}>{item.title}</Text>}
      getItemLayout={(_, index) => ({ length: ROW_HEIGHT, offset: ROW_HEIGHT * index, index })}
      estimatedItemSize={ROW_HEIGHT}
      initialNumToRender={12}
      windowSize={7}
    />
  );
}

import { useEffect, useState } from 'react';
import { AsyncStorage } from 'react-native';

const KEY = 'onboarding:done';

export function useOnboardingDone(): boolean | null {
  const [done, setDone] = useState<boolean | null>(null);

  useEffect(() => {
    let cancelled = false;
    AsyncStorage.getItem(KEY)
      .then((value) => !cancelled && setDone(value === '1'))
      .catch(() => !cancelled && setDone(false));
    return () => {
      cancelled = true;
    };
  }, []);

  return done;
}

type RefundResult = { id: string; status: 'pending' | 'succeeded' };

export async function requestRefund(orderId: string, signal?: AbortSignal): Promise<RefundResult> {
  const res = await fetch('https://api.payments.example.com/v1/refunds', {
    method: 'POST',
    signal,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${process.env.EXPO_PUBLIC_PAYMENTS_SECRET_KEY}`,
    },
    body: JSON.stringify({ order: orderId }),
  });
  if (!res.ok) {
    throw new Error(`Refund failed with status ${res.status}`);
  }
  return (await res.json()) as RefundResult;
}
